import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf
import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.patch
import org.springframework.test.web.servlet.request.MockHttpServletRequestDsl
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.status
import java.math.BigDecimal
import java.time.Instant
import java.time.LocalDate
import java.util.UUID

@WebMvcTest(controllers = [GroupSessionWorkoutController::class])
@Import(
    GroupSessionWorkoutController::class,
    GroupSessionExceptionHandler::class,
    WorkoutExceptionHandler::class,
    GroupSessionFloorSetConflictTest.TestConfig::class,
)
class GroupSessionFloorSetConflictTest {
    @Autowired lateinit var mockMvc: MockMvc

    @Autowired lateinit var groupSessionQueryService: GroupSessionQueryService

    @Autowired lateinit var workoutFieldPatchService: WorkoutFieldPatchService

    @Autowired lateinit var workoutService: WorkoutService

    @Autowired lateinit var workoutFinishReadinessService: WorkoutFinishReadinessService

    @Autowired lateinit var responses: WorkoutResponseAssembler

    private val owner = UUID.fromString("11111111-1111-1111-1111-111111111111")
    private val jana = UUID.fromString("22222222-2222-2222-2222-222222222222")
    private val sessionId = UUID.randomUUID()
    private val workoutId = UUID.randomUUID()
    private val setId = UUID.randomUUID()
    private val changedAt = Instant.parse("2026-10-14T09:00:00Z")

    @BeforeEach
    fun resetMocks() {
        clearMocks(groupSessionQueryService, workoutFieldPatchService, workoutService, workoutFinishReadinessService, responses)
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
    }

    private fun basePath() = "/api/group-sessions/$sessionId/participants/$jana/workout/sets/$setId"

    private fun MockHttpServletRequestDsl.floorBody(body: String) {
        with(user(owner.toString()))
        with(csrf())
        contentType = MediaType.APPLICATION_JSON
        content = body
    }

    private fun storedSet(
        updatedBy: UUID? = jana,
        updatedAt: Instant? = changedAt,
    ) = WorkoutSet(
        id = setId,
        position = 1,
        weight = SetWeight.Measured(BigDecimal("62.5")),
        effort = SetEffort.Count(8),
        confirmedAt = changedAt,
        updatedAt = updatedAt,
        updatedBy = updatedBy,
    )

    private fun changed(set: WorkoutSet) = WorkoutSetChangedException(set)

    @Test
    fun `an expected body passes the compare-and-set and the driver as actor to the service`() {
        every {
            workoutFieldPatchService.patchSet(
                jana,
                workoutId,
                setId,
                SetWeight.Measured(BigDecimal("60")),
                SetEffort.Count(8),
                true,
                owner,
                SetValues(SetWeight.Measured(BigDecimal("60")), SetEffort.Count(8), confirmed = false),
            )
        } throws changed(storedSet())
        every { groupSessionQueryService.profileOf(jana) } returns profile(jana, "Jana")

        mockMvc
            .patch(basePath(), patchBody("""{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":8},"confirmed":true,"expected":{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":8},"confirmed":false}}"""))
            .andExpect { status { isConflict() } }

        verify {
            workoutFieldPatchService.patchSet(
                jana,
                workoutId,
                setId,
                SetWeight.Measured(BigDecimal("60")),
                SetEffort.Count(8),
                true,
                owner,
                SetValues(SetWeight.Measured(BigDecimal("60")), SetEffort.Count(8), confirmed = false),
            )
        }
    }

    @Test
    fun `a changed stamped set answers 409 set_changed with its current values and author`() {
        every { workoutFieldPatchService.patchSet(any(), any(), any(), any(), any(), any(), any(), any()) } throws
            changed(storedSet())
        every { groupSessionQueryService.profileOf(jana) } returns profile(jana, "Jana")

        mockMvc
            .patch(basePath(), patchBody("""{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":8},"confirmed":true,"expected":{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":8},"confirmed":false}}"""))
            .andExpect {
                status { isConflict() }
                jsonPath("$.code") { value("set_changed") }
                jsonPath("$.detail") { value("This set was changed on another phone.") }
                jsonPath("$.current.weight.kind") { value("MEASURED") }
                jsonPath("$.current.weight.value") { value(62.5) }
                jsonPath("$.current.effort.kind") { value("COUNT") }
                jsonPath("$.current.effort.value") { value(8) }
                jsonPath("$.current.confirmed") { value(true) }
                jsonPath("$.updatedBy.id") { value(jana.toString()) }
                jsonPath("$.updatedBy.displayName") { value("Jana") }
                jsonPath("$.updatedAt") { value("2026-10-14T09:00:00Z") }
            }
    }

    @Test
    fun `an unstamped set answers 409 set_changed with null author and time`() {
        every { workoutFieldPatchService.patchSet(any(), any(), any(), any(), any(), any(), any(), any()) } throws
            changed(storedSet(updatedBy = null, updatedAt = null))

        mockMvc
            .patch(basePath(), patchBody("""{"weight":null,"effort":null,"confirmed":true,"expected":{"weight":null,"effort":null,"confirmed":false}}"""))
            .andExpect {
                status { isConflict() }
                jsonPath("$.code") { value("set_changed") }
                jsonPath("$.updatedBy") { doesNotExist() }
                jsonPath("$.updatedAt") { doesNotExist() }
            }
    }

    @Test
    fun `an unknown field in the floor set body answers 400`() {
        mockMvc
            .patch(basePath(), patchBody("""{"weight":null,"effort":null,"confirmed":true,"foo":1}"""))
            .andExpect { status { isBadRequest() } }
    }

    private fun profile(
        userId: UUID,
        name: String,
    ) = ParticipantProfile(userId = userId, displayName = name, slug = name.lowercase(), avatarUrl = null, gender = null)

    @TestConfiguration
    class TestConfig {
        @Bean
        fun groupSessionQueryService(): GroupSessionQueryService = mockk()

        @Bean
        fun workoutService(): WorkoutService = mockk()

        @Bean
        fun workoutFieldPatchService(): WorkoutFieldPatchService = mockk()

        @Bean
        fun workoutFinishReadinessService(): WorkoutFinishReadinessService = mockk()

        @Bean
        fun workoutResponseAssembler(): WorkoutResponseAssembler = mockk()
    }
}

